import{_ as t,o as a,c as n,a3 as i}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"工程体系总览","description":"","frontmatter":{"title":"工程体系总览"},"headers":[],"relativePath":"frontend/guide/engineering/index.md","filePath":"frontend/guide/engineering/index.md","lastUpdated":1784378817000}'),r={name:"frontend/guide/engineering/index.md"};function d(l,e,o,s,h,c){return a(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="工程体系" tabindex="-1">工程体系 <a class="header-anchor" href="#工程体系" aria-label="Permalink to &quot;工程体系&quot;">​</a></h1><p>工程体系关注的不是“功能能否运行”，而是一个系统能否持续、稳定、低成本地交付。它把代码扩展到工具链、架构、质量、性能、安全、体验、可靠性和运行环境，建立从开发到生产的完整闭环。</p><p>资深工程师需要同时理解局部实现和系统约束：一次构建为什么变慢、一个模块为什么难以修改、一次发布为什么不可回滚、一个线上问题为什么无法复现，都属于工程问题。</p><h2 id="工程全景" tabindex="-1">工程全景 <a class="header-anchor" href="#工程全景" aria-label="Permalink to &quot;工程全景&quot;">​</a></h2><table tabindex="0"><thead><tr><th>章节</th><th>关注范围</th><th>关键产出</th></tr></thead><tbody><tr><td><a href="/frontend/guide/engineering/tooling/package-management">前端工程化</a></td><td>依赖、编译、构建、规范、环境与发布链路</td><td>可重复、可追踪的开发与交付流程</td></tr><tr><td><a href="/frontend/guide/engineering/architecture/principles-boundaries">前端架构与治理</a></td><td>系统边界、架构评审、规范治理、扩展机制与演进</td><td>清晰的依赖方向和可持续的结构</td></tr><tr><td><a href="/frontend/guide/engineering/quality/testing-strategy">测试与质量</a></td><td>Code Review、测试分层、发布验证和质量度量</td><td>与风险匹配的质量保障体系</td></tr><tr><td><a href="/frontend/guide/engineering/performance/metrics-budgets">性能工程与优化</a></td><td>指标、测量、优化与性能预算</td><td>基于证据的性能改进闭环</td></tr><tr><td><a href="/frontend/guide/engineering/security/threat-model">前端安全与隐私</a></td><td>威胁、身份、浏览器隔离和数据边界</td><td>可验证的安全控制与隐私约束</td></tr><tr><td><a href="/frontend/guide/engineering/experience/accessibility">体验与可访问性工程</a></td><td>无障碍、适配、国际化和设计一致性</td><td>可服务不同用户和环境的产品体验</td></tr><tr><td><a href="/frontend/guide/engineering/reliability/observability">可观测性与可靠性</a></td><td>日志、监控、韧性、值班、故障响应和复盘</td><td>能发现、定位、恢复并减少生产风险的系统</td></tr><tr><td><a href="/frontend/guide/engineering/server/node-runtime">服务端工程</a></td><td>Node.js、API、NestJS、数据存储、异步任务与部署</td><td>能守住前后端边界并完成必要服务端工作</td></tr></tbody></table><h2 id="工程闭环" tabindex="-1">工程闭环 <a class="header-anchor" href="#工程闭环" aria-label="Permalink to &quot;工程闭环&quot;">​</a></h2><p>工程能力应围绕同一个反馈循环建立：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>明确约束 -&gt; 设计边界 -&gt; 实现与验证 -&gt; 构建与发布</span></span>
<span class="line"><span>    -&gt; 监控真实结果 -&gt; 定位问题 -&gt; 修正系统与流程</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>工具并不是工程体系的起点。先明确规模、团队、风险和交付目标，再决定是否需要 Monorepo、微前端、复杂测试矩阵或平台化能力。脱离约束堆叠工具，只会增加维护成本。</p><h2 id="推荐路径" tabindex="-1">推荐路径 <a class="header-anchor" href="#推荐路径" aria-label="Permalink to &quot;推荐路径&quot;">​</a></h2><h3 id="业务应用工程师" tabindex="-1">业务应用工程师 <a class="header-anchor" href="#业务应用工程师" aria-label="Permalink to &quot;业务应用工程师&quot;">​</a></h3><p>先学习前端工程化、测试与质量、性能工程与优化、前端安全与隐私、可观测性与可靠性，再根据业务补充架构和服务端工程。</p><h3 id="架构与基础设施方向" tabindex="-1">架构与基础设施方向 <a class="header-anchor" href="#架构与基础设施方向" aria-label="Permalink to &quot;架构与基础设施方向&quot;">​</a></h3><p>以工程化和前端架构与治理为主线，深入依赖治理、构建系统、Monorepo、发布体系、前端平台、可观测性和渐进式演进。</p><h3 id="全栈与专项方向" tabindex="-1">全栈与专项方向 <a class="header-anchor" href="#全栈与专项方向" aria-label="Permalink to &quot;全栈与专项方向&quot;">​</a></h3><p>在通用工程基础上，根据岗位继续学习服务端工程，或进入<a href="/frontend/topics/">专题进阶</a>中的跨端、可视化和 AI 应用等方向。这里的服务端内容以支撑前端交付为边界，不替代完整的后端知识体系。</p><h2 id="与其他模块的边界" tabindex="-1">与其他模块的边界 <a class="header-anchor" href="#与其他模块的边界" aria-label="Permalink to &quot;与其他模块的边界&quot;">​</a></h2><ul><li><a href="/frontend/guide/core/">核心知识</a>提供语言、浏览器、框架和应用模型。</li><li>本模块沉淀可复用的工程机制，不绑定某个具体项目。</li><li><a href="/frontend/topics/">专题进阶</a>展开只在特定产品或岗位中深入使用的专业领域。</li><li><a href="/frontend/deep-dive/">原理深挖</a>研究工程机制背后的运行原理与实现细节。</li><li><a href="/frontend/decisions/">技术决策</a>回答在多个工程方案之间如何选择。</li><li><a href="/frontend/practices/">项目实战</a>验证工程机制在具体业务和团队约束下是否成立。</li></ul><h2 id="掌握标准" tabindex="-1">掌握标准 <a class="header-anchor" href="#掌握标准" aria-label="Permalink to &quot;掌握标准&quot;">​</a></h2><ul><li>能为项目建立从本地开发到生产回滚的可重复链路。</li><li>能根据风险设计测试层级，而不是追求覆盖率数字本身。</li><li>能用数据定位性能和可靠性问题，并验证优化收益。</li><li>能识别架构、依赖、安全和隐私边界中的长期风险。</li><li>能判断一项工程能力应该由业务项目、共享基础设施还是组织流程承担。</li></ul>`,20)])])}const g=t(r,[["render",d]]);export{u as __pageData,g as default};
